css:
:scope { width: min(100%, 859px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 24; grid-row: 1 / span 14; font-family: var(--os-font-label); font-size: 176px; font-weight: 400; line-height: 0.6; letter-spacing: 0em; text-align: center; color: var(--os-color-background); }
.gx__i2 { grid-column: 3 / span 19; grid-row: 12 / span 11; font-family: var(--os-font-label); font-size: 127px; font-weight: 400; line-height: 0.5; letter-spacing: 0em; text-transform: uppercase; text-align: center; color: var(--os-color-background); }
.gx__i3 { grid-column: 6 / span 13; grid-row: 21 / span 8; font-family: var(--os-font-label); font-size: 47px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; text-align: center; color: var(--os-color-background); }
.gx__i4 { grid-column: 9 / span 8; grid-row: 29 / span 4; font-family: var(--os-font-label); font-size: 41px; font-weight: 400; line-height: 0.7; letter-spacing: 0em; color: var(--os-color-background); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 141px; }
  .gx__i2 { font-family: var(--os-font-label); font-size: 102px; }
  .gx__i3 { font-family: var(--os-font-label); font-size: 38px; }
  .gx__i4 { font-family: var(--os-font-label); font-size: 33px; }
}
